"""Thread-safe capture of the redirect generated by the existing Audible backend."""
import threading
import time
from urllib.parse import parse_qs, urlsplit

from .files import Cancelled, UtilityError

LOGIN_HOSTS = {"www.amazon.com", "www.audible.com"}


def _parse(url):
    try:
        if not isinstance(url, str) or len(url) > 65536 or any(ord(c) < 32 for c in url):
            raise ValueError
        parsed = urlsplit(url)
        if (parsed.scheme != "https" or parsed.hostname not in LOGIN_HOSTS
                or parsed.port not in {None, 443} or parsed.username or parsed.password
                or parsed.fragment):
            raise ValueError
        return parsed
    except ValueError:
        raise UtilityError("The sign-in response was not a valid Amazon/Audible HTTPS callback.") from None


def callback_target(login_url):
    parsed = _parse(login_url)
    values = parse_qs(parsed.query).get("openid.return_to", [])
    if parsed.path != "/ap/signin" or len(values) != 1:
        raise UtilityError("The Audible backend did not provide a supported sign-in callback.")
    target = _parse(values[0])
    if target.path != "/ap/maplanding" or target.query:
        raise UtilityError("The Audible backend did not provide a supported sign-in callback.")
    return values[0]


def validate_redirect(url, expected=None):
    parsed = _parse(url)
    if parsed.path != "/ap/maplanding":
        raise UtilityError("Amazon did not return the expected sign-in callback.")
    if expected:
        target = _parse(expected)
        if (parsed.hostname, parsed.path) != (target.hostname, target.path):
            raise UtilityError("Amazon returned a callback for a different sign-in destination.")
    query = parse_qs(parsed.query, keep_blank_values=True)
    codes = query.get("openid.oa2.authorization_code", [])
    if (len(codes) != 1 or not codes[0].strip() or "error" in query or "openid.error" in query
            or query.get("openid.mode") == ["cancel"]):
        raise UtilityError("Amazon did not return a successful authorization. Please try signing in again.")
    return url


class LoginRequest:
    """No browser passwords, cookies or page contents enter this object."""

    def __init__(self, url, cancel, timeout=600):
        self.url = url
        self.target = callback_target(url)
        self.cancel_event = cancel
        self.deadline = time.monotonic() + timeout
        self.ready = threading.Event()
        self._lock = threading.Lock()
        self._response = None
        self._failure = None

    def fail(self, error):
        with self._lock:
            if not self.ready.is_set():
                self._failure = error
                self.ready.set()

    def cancel(self):
        self.cancel_event.set()
        self.fail(Cancelled("Audible sign-in canceled. Your saved account and media licenses were kept."))

    def receive(self, uri):
        try:
            parsed, target = urlsplit(uri), urlsplit(self.target)
            if (parsed.hostname, parsed.path) != (target.hostname, target.path):
                return False
            response = validate_redirect(uri, self.target)
        except (UtilityError, ValueError):
            self.fail(UtilityError("Amazon did not return a successful authorization. Please try signing in again."))
            return True
        with self._lock:
            if not self.ready.is_set() and not self.cancel_event.is_set():
                self._response = response
                self.ready.set()
        return True

    def wait(self):
        while not self.ready.wait(0.1):
            if self.cancel_event.is_set():
                self.cancel()
            elif time.monotonic() >= self.deadline:
                self.fail(UtilityError("Audible sign-in timed out. Click Login to Audible to try again."))
        with self._lock:
            response, self._response = self._response, None
            self.url = ""
            if self.cancel_event.is_set():
                raise Cancelled("Audible sign-in canceled. Your saved account and media licenses were kept.")
            if self._failure:
                raise self._failure
            if not response:
                raise UtilityError("Amazon did not return a successful authorization.")
            return response
